import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-DrdKnICy.js";var i=JSON.parse(`{"path":"/english/vocabulary/physical-geography/oceans-and-water/","title":"CH1.7 海洋、河流与水循环 | 英语","lang":"zh-CN","frontmatter":{"title":"CH1.7 海洋、河流与水循环","createTime":"2026-11-18T09:50:00.000Z","permalink":"/english/vocabulary/physical-geography/oceans-and-water/"},"readingTime":{"minutes":30.85,"words":9256},"git":{"createdTime":1795010783000},"filePathRelative":"english/vocabulary/physical-geography/7.oceans-and-water.md","headers":[],"bulletin":false}`),a={name:`7.oceans-and-water.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="vocab-card"><h2 id="mediterranean" tabindex="-1"><a class="header-anchor" href="#mediterranean"><span>Mediterranean</span></a></h2><p class="vc-meta"><strong>/ˌmedɪtəˈreɪniən/</strong> · adj · 形容词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：地中海的；地中海气候的</li><li>名词：地中海（the Mediterranean）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the Mediterranean</td><td>地中海</td></tr><tr><td>the Mediterranean Sea</td><td>地中海（全称）</td></tr><tr><td>Mediterranean climate</td><td>地中海气候</td></tr><tr><td>Mediterranean diet</td><td>地中海饮食</td></tr><tr><td>the Mediterranean basin</td><td>地中海盆地</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the Mediterranean and the countries along its northern coast.</p><blockquote><p>该地图显示了地中海及其北岸各国。</p></blockquote><p><strong>Writing Task 2</strong> Mediterranean climates bring mild wet winters and hot dry summers, conditions well suited to viticulture.</p><blockquote><p>地中海气候冬季温和多雨、夏季炎热干燥，非常适合葡萄种植。</p></blockquote><p><strong>Speaking</strong> I&#39;d rather swim in the Mediterranean than in the North Sea — it&#39;s about ten degrees warmer.</p><blockquote><p>我宁愿在地中海游泳，也不愿去北海，水温差了大约十度。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>the Med</td><td>地中海</td><td>口语简称，非正式</td></tr><tr><td>the Mediterranean basin</td><td>地中海盆地</td><td>学术表述，含周边陆地</td></tr><tr><td>mid-latitude sea</td><td>中纬度海</td><td>气候学描述，不用作地名</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>mediterraneus</em> = <em>medius</em>（中间）+ <em>terra</em>（土地）→ &quot;被陆地围在中间的&quot;</li><li><strong>Family:</strong> Mediterranean 地中海的 / terrace 梯田 / terrain 地形 / territory 领土</li><li><strong>Memory Tip:</strong> medius + terra + -aneus，名字本身就是一张地图：这片海几乎被欧、非、亚三洲合抱，所以叫&quot;陆地中间的海&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>必须加 the：the Mediterranean。</li><li>拼写 Medi-terra-nean，中间是 terra（土地），别写成 <s>Mediteranian</s>。</li><li>气候类型说 Mediterranean climate，首字母习惯大写。</li></ul></div><div class="vocab-card"><h2 id="atlantic" tabindex="-1"><a class="header-anchor" href="#atlantic"><span>Atlantic</span></a></h2><p class="vc-meta"><strong>/ətˈlæntɪk/</strong> · adj · 形容词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：大西洋的</li><li>名词：大西洋（the Atlantic）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the Atlantic Ocean</td><td>大西洋</td></tr><tr><td>across the Atlantic</td><td>横渡／横跨大西洋</td></tr><tr><td>the North Atlantic</td><td>北大西洋</td></tr><tr><td>transatlantic flight</td><td>跨大西洋航班</td></tr><tr><td>the Atlantic coast</td><td>大西洋沿岸</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows average sea surface temperatures across the North Atlantic.</p><blockquote><p>该地图显示了北大西洋的海表平均温度分布。</p></blockquote><p><strong>Writing Task 2</strong> The Atlantic has warmed measurably over the past century, shifting fish stocks northwards.</p><blockquote><p>过去一个世纪大西洋明显变暖，鱼群随之北移。</p></blockquote><p><strong>Speaking</strong> We crossed the Atlantic by cargo ship — twelve days and not a single other vessel in sight.</p><blockquote><p>我们搭货轮横渡大西洋，十二天里一艘别的船都没看见。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>transatlantic</td><td>跨大西洋的</td><td>形容词，用于航线、关系</td></tr><tr><td>the Pond</td><td>大西洋</td><td>英美俚语，戏称&quot;池塘&quot;</td></tr><tr><td>the North Atlantic</td><td>北大西洋</td><td>更具体的地理范围</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊 <em>Atlas</em>（阿特拉斯，擎天巨神）→ &quot;阿特拉斯之海&quot;</li><li><strong>Family:</strong> Atlantic 大西洋 / transatlantic 跨大西洋的 / atlas 地图册</li><li><strong>Memory Tip:</strong> 希腊神话里阿特拉斯在极西处擎天，所以西边那片海叫&quot;阿特拉斯之海&quot;。地图册叫 atlas，是因为古地图集封面常画他扛着地球。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>加冠词：the Atlantic / the Atlantic Ocean。</li><li>transatlantic 连写，不加连字符。</li><li>读音 /ətˈlæntɪk/，重音在第二音节，别读成 /ˌætˈlæntɪk/。</li></ul></div><div class="vocab-card"><h2 id="pacific" tabindex="-1"><a class="header-anchor" href="#pacific"><span>Pacific</span></a></h2><p class="vc-meta"><strong>/pəˈsɪfɪk/</strong> · adj · 形容词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：太平洋的；（书面）和平的，平静的</li><li>名词：太平洋（the Pacific）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the Pacific Ocean</td><td>太平洋</td></tr><tr><td>the Pacific Rim</td><td>环太平洋地区</td></tr><tr><td>Asia-Pacific</td><td>亚太地区</td></tr><tr><td>Pacific island nations</td><td>太平洋岛国</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares annual rainfall across several Pacific island states.</p><blockquote><p>该图表比较了几个太平洋岛国的年降水量。</p></blockquote><p><strong>Writing Task 2</strong> The Pacific covers roughly a third of the planet&#39;s surface, yet its islands hold only a tiny share of its population.</p><blockquote><p>太平洋约占地球表面的三分之一，但其岛屿人口只占极小比例。</p></blockquote><p><strong>Speaking</strong> We flew over the Pacific for eleven hours — nothing but water the whole way.</p><blockquote><p>我们在太平洋上空飞了十一个小时，一路只有水。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>peaceful</td><td>和平的</td><td>对应形容词义，更常用</td></tr><tr><td>calm</td><td>平静的</td><td>形容水面、情绪</td></tr><tr><td>the South Seas</td><td>南海诸岛</td><td>文学化，指南太平洋</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>pacificus</em> = <em>pax</em>（和平）+ <em>facere</em>（做）→ &quot;缔造和平的&quot;</li><li><strong>Family:</strong> Pacific 太平洋 / pacific 和平的 / pacify 平定 / pacifist 和平主义者</li><li><strong>Memory Tip:</strong> pax = 和平（同 pact 条约、pacify 安抚）。麦哲伦从风暴海域驶入这片风平浪静的大洋，就取名&quot;太平&quot;——讽刺的是它并不太平。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>作地名大写并加 the：the Pacific。</li><li>形容词&quot;和平的&quot;写作 pacific 但罕用，日常用 peaceful。</li><li>拼写 Pa-ci-fic，别写成 <s>Pacifie</s>（原清单即为此误）。</li></ul></div><div class="vocab-card"><h2 id="ocean" tabindex="-1"><a class="header-anchor" href="#ocean"><span>Ocean</span></a></h2><p class="vc-meta"><strong>/ˈəʊʃn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>海洋，大洋；（一片）海域</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>ocean currents</td><td>洋流</td></tr><tr><td>the ocean floor</td><td>海底</td></tr><tr><td>a drop in the ocean</td><td>沧海一粟</td></tr><tr><td>oceanography</td><td>海洋学</td></tr><tr><td>the open ocean</td><td>外海，公海</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how ocean currents redistribute heat away from the tropics.</p><blockquote><p>该示意图显示了洋流如何把热量从热带向外输送。</p></blockquote><p><strong>Writing Task 2</strong> Oceans absorb roughly a quarter of the carbon dioxide that humans release each year.</p><blockquote><p>海洋吸收了人类每年排放的二氧化碳的约四分之一。</p></blockquote><p><strong>Speaking</strong> I love being near the ocean — the sound of it puts me straight to sleep.</p><blockquote><p>我喜欢待在近海的地方，海浪声一下就把我哄睡了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>sea</td><td>海</td><td>常可互换，sea 更偏&quot;一片水域&quot;</td></tr><tr><td>the deep</td><td>深海</td><td>文学化，带神秘感</td></tr><tr><td>waters</td><td>水域</td><td>正式，常用于法律、航运</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊 <em>Okeanos</em>（环绕大地的巨河之神）→ 拉丁 <em>oceanus</em></li><li><strong>Family:</strong> ocean 海洋 / oceanic 海洋的 / oceanography 海洋学 / Oceania 大洋洲</li><li><strong>Memory Tip:</strong> 希腊人以为大地被一条巨河环绕，河神叫 Okeanos。所以 a drop in the ocean（沧海一粟）的字面感特别强。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>泛指时加 the：the ocean；特指某洋才可数：the Atlantic Ocean。</li><li>&quot;海洋学&quot;是 oceanography，不是 <s>oceanology</s>。</li><li>ocean 与 sea 常可互换，但固定名称不能改：the South China Sea。</li></ul></div><div class="vocab-card"><h2 id="marine" tabindex="-1"><a class="header-anchor" href="#marine"><span>Marine</span></a></h2><p class="vc-meta"><strong>/məˈriːn/</strong> · adj · 形容词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：海洋的，海生的；海运的</li><li>名词：海军陆战队士兵</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>marine life</td><td>海洋生物</td></tr><tr><td>marine ecosystem</td><td>海洋生态系统</td></tr><tr><td>marine pollution</td><td>海洋污染</td></tr><tr><td>marine biology</td><td>海洋生物学</td></tr><tr><td>marine transport</td><td>海上运输</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows marine protected areas along the southern coast.</p><blockquote><p>该地图显示了南部沿海的海洋保护区。</p></blockquote><p><strong>Writing Task 2</strong> Plastic waste harms marine life at every level of the food chain.</p><blockquote><p>塑料垃圾危害着食物链每一层级的海洋生物。</p></blockquote><p><strong>Speaking</strong> I wanted to study marine biology, but I&#39;m a terrible swimmer.</p><blockquote><p>我本想学海洋生物学，但我游泳特别差。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>maritime</td><td>海事的，海运的</td><td>偏航运、法律，不指生态</td></tr><tr><td>oceanic</td><td>海洋的</td><td>学术，强调大洋属性</td></tr><tr><td>naval</td><td>海军的</td><td>只用于军事</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>mare</em>（海）→ <em>marinus</em></li><li><strong>Family:</strong> marine 海洋的 / maritime 海事的 / submarine 潜水艇 / mermaid 美人鱼</li><li><strong>Memory Tip:</strong> mare = 海。sub-（下）+ marine = 潜艇；mermaid = mere（海）+ maid（少女）。注意英语里 mare 又指&quot;母马&quot;，别被带偏。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>marine 是形容词，不能单独当&quot;海洋&quot;用：<s>the marine</s> ✘ → the sea。</li><li>&quot;海洋生物&quot;是 marine life（不可数），不说 <s>marine lives</s>。</li><li>生态语境用 marine，航运与法律语境用 maritime。</li></ul></div><div class="vocab-card"><h2 id="navigation" tabindex="-1"><a class="header-anchor" href="#navigation"><span>Navigation</span></a></h2><p class="vc-meta"><strong>/ˌnævɪˈɡeɪʃn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>航行，航海；导航</li><li>航海学，航行术</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>navigation system</td><td>导航系统</td></tr><tr><td>satellite navigation</td><td>卫星导航</td></tr><tr><td>inland navigation</td><td>内河航运</td></tr><tr><td>freedom of navigation</td><td>航行自由</td></tr><tr><td>a navigation channel</td><td>航道</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the navigation channel dredged through the estuary.</p><blockquote><p>该地图显示了穿过河口疏浚而成的航道。</p></blockquote><p><strong>Writing Task 2</strong> Satellite navigation has made shipping safer, but also more dependent on fragile technology.</p><blockquote><p>卫星导航使航运更安全，但也使其更依赖脆弱的技术系统。</p></blockquote><p><strong>Speaking</strong> My sense of navigation is awful — I get lost in car parks.</p><blockquote><p>我的方向感极差，在停车场里都能迷路。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>sailing</td><td>航行</td><td>强调用帆、出海这个行为</td></tr><tr><td>shipping</td><td>航运</td><td>强调货运业</td></tr><tr><td>pilotage</td><td>引航</td><td>专业术语，指引水员领航</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>navis</em>（船）+ <em>agere</em>（驱动）→ <em>navigare</em>（驾船）</li><li><strong>Family:</strong> navigation 航行；导航 / navigate 导航；航行 / navigator 航海者 / navy 海军 / naval 海军的</li><li><strong>Memory Tip:</strong> navis = 船（同 navy、naval），ag- = 驱动。驾船前行就是 navigate，如今也用于&quot;在网站里找路&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>名词 navigation 与动词 navigate 别混用。</li><li>&quot;导航系统&quot;用 navigation system，英式口语常说 sat-nav。</li><li>freedom of navigation 是国际法固定说法，介词用 of。</li></ul></div><div class="vocab-card"><h2 id="gulf" tabindex="-1"><a class="header-anchor" href="#gulf"><span>Gulf</span></a></h2><p class="vc-meta"><strong>/ɡʌlf/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>海湾（比 bay 更大、更深入陆地）</li><li>巨大分歧，鸿沟</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the Gulf of Mexico</td><td>墨西哥湾</td></tr><tr><td>the Persian Gulf</td><td>波斯湾</td></tr><tr><td>the Gulf Stream</td><td>湾流</td></tr><tr><td>a widening gulf between</td><td>……之间不断扩大的鸿沟</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the Gulf Stream flowing north-east across the Atlantic.</p><blockquote><p>该地图显示了湾流向东北横穿大西洋的路径。</p></blockquote><p><strong>Writing Task 2</strong> A widening gulf between coastal cities and inland regions is driving internal migration.</p><blockquote><p>沿海城市与内陆地区之间不断扩大的差距，正推动着国内人口迁移。</p></blockquote><p><strong>Speaking</strong> The hotel overlooks the gulf, and at sunset the water turns pink.</p><blockquote><p>酒店正对海湾，日落时水面会变成粉色。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>bay</td><td>湾</td><td>规模较小，开口较宽</td></tr><tr><td>bight</td><td>大湾</td><td>弧形浅湾，地理术语</td></tr><tr><td>strait</td><td>海峡</td><td>两侧陆地夹峙，不是湾</td></tr><tr><td>chasm</td><td>鸿沟</td><td>只对应抽象&quot;分歧&quot;义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊 <em>kolpos</em>（怀抱、湾）→ 法语 <em>golfe</em></li><li><strong>Family:</strong> gulf 海湾 / engulf 吞没 / Gulf Stream 湾流</li><li><strong>Memory Tip:</strong> kolpos 原义&quot;怀抱&quot;——海湾就像大地张开的手臂。抽象义 a gulf between A and B 就是&quot;鸿沟&quot;，与 embrace 的意象同源。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>地名加 the：the Gulf of Mexico、the Persian Gulf。</li><li>与 golf（高尔夫）只差一个 u，拼写要看清。</li><li>bay 与 gulf 主要是规模差别，gulf 更大、更深入内陆。</li></ul></div><div class="vocab-card"><h2 id="beach" tabindex="-1"><a class="header-anchor" href="#beach"><span>Beach</span></a></h2><p class="vc-meta"><strong>/biːtʃ/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：海滩，沙滩；（砾石）滩</li><li>动词：使搁浅（beached whale）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a sandy beach</td><td>沙滩</td></tr><tr><td>on the beach</td><td>在海滩上</td></tr><tr><td>a pebble beach</td><td>卵石滩</td></tr><tr><td>beach erosion</td><td>海滩侵蚀</td></tr><tr><td>a beach resort</td><td>海滨度假区</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows how the beach has narrowed since the sea wall was built.</p><blockquote><p>该地图显示了自海堤建成以来海滩变窄的情况。</p></blockquote><p><strong>Writing Task 2</strong> Beaches are dynamic landforms that shift with every storm rather than stable lines on a map.</p><blockquote><p>海滩是动态地貌，会随每次风暴而移动，并不是地图上那条固定的线。</p></blockquote><p><strong>Speaking</strong> We spent the whole afternoon on the beach doing absolutely nothing.</p><blockquote><p>我们在海滩上待了一整个下午，什么也没干。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>shore</td><td>岸</td><td>泛指水陆交界，不限沙质</td></tr><tr><td>coast</td><td>海岸</td><td>指整条海岸线或沿海地区</td></tr><tr><td>seaside</td><td>海滨</td><td>英式，偏度假语境</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>bæce</em>（溪、砾石岸）</li><li><strong>Family:</strong> beach 海滩 / beachy 多沙滩的 / beachcomber 海滨拾荒者 / beachfront 海滨的</li><li><strong>Memory Tip:</strong> 介词分两种：on the beach 是在沙滩上（脚踩沙），at the beach 是在海边这个地方（可能在海滩边的店里）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词用 on the beach，不用 <s>in</s>。</li><li>可数：a beach / two beaches。</li><li>beach 是一段沙岸，coast 是整条海岸线，别互替。</li></ul></div><div class="vocab-card"><h2 id="coast" tabindex="-1"><a class="header-anchor" href="#coast"><span>Coast</span></a></h2><p class="vc-meta"><strong>/kəʊst/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：海岸，沿海地区</li><li>动词：沿海岸航行；（靠惯性）滑行</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the east coast</td><td>东海岸</td></tr><tr><td>off the coast</td><td>在近海，离岸</td></tr><tr><td>coastal erosion</td><td>海岸侵蚀</td></tr><tr><td>coast to coast</td><td>从东岸到西岸</td></tr><tr><td>a coastal town</td><td>沿海城镇</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows changes in land use along the coast between 1990 and 2020.</p><blockquote><p>该地图显示了 1990 至 2020 年间沿海土地利用的变化。</p></blockquote><p><strong>Writing Task 2</strong> In much of Asia, coastal cities are expanding faster than inland ones.</p><blockquote><p>在亚洲大部分地区，沿海城市的扩张速度快于内陆城市。</p></blockquote><p><strong>Speaking</strong> We drove down the coast road — the views were incredible.</p><blockquote><p>我们沿着海岸公路往南开，风景美得难以置信。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>shoreline</td><td>滨线</td><td>水陆交界那条线，更技术化</td></tr><tr><td>seaboard</td><td>沿海地带</td><td>美式书面，多用于东岸</td></tr><tr><td>littoral</td><td>沿岸的</td><td>学术用语，生态与法律文本</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>costa</em>（肋、侧）→ 法语 <em>coste</em> → coast</li><li><strong>Family:</strong> coast 海岸 / coastal 沿海的 / coastline 海岸线 / coaster 沿海船</li><li><strong>Memory Tip:</strong> costa = 肋骨。把大地想成身体，海岸就是它的&quot;肋侧&quot;。同源词还有 accost（上前搭话，原义&quot;贴到身边&quot;）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>加冠词 the coast；&quot;沿海地区&quot;用 coastal areas，不用 <s>coast areas</s>。</li><li>off the coast 指&quot;离岸的海上&quot;，不是&quot;在岸上&quot;。</li><li>coastal 是形容词，coast 是名词，别写 <s>coast town</s>（应为 coastal town）。</li></ul></div><div class="vocab-card"><h2 id="shore" tabindex="-1"><a class="header-anchor" href="#shore"><span>Shore</span></a></h2><p class="vc-meta"><strong>/ʃɔː(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>岸，滨（海、湖、河均可）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>on the shore</td><td>在岸上</td></tr><tr><td>the shore of the lake</td><td>湖岸</td></tr><tr><td>shoreline</td><td>岸线</td></tr><tr><td>offshore</td><td>离岸的</td></tr><tr><td>shore up</td><td>支撑，稳住</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The photograph shows fishing boats pulled up on the shore at low tide.</p><blockquote><p>照片显示了退潮时被拖上岸的渔船。</p></blockquote><p><strong>Writing Task 2</strong> Rising sea levels are pushing salt water further inland, threatening low-lying shores.</p><blockquote><p>海平面上升正把咸水推向更内陆的地方，威胁着低洼海岸。</p></blockquote><p><strong>Speaking</strong> We sat on the shore and watched the ferry come in.</p><blockquote><p>我们坐在岸边看渡轮进港。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>bank</td><td>河岸</td><td>只用于河流、运河</td></tr><tr><td>beach</td><td>沙滩</td><td>特指沙质或砾石滩</td></tr><tr><td>waterfront</td><td>滨水区</td><td>强调城市临水的那一带</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 中古英语 <em>schore</em>，或与中低德语 <em>schore</em>（分界、裂开）有关 → 水陆分界</li><li><strong>Family:</strong> shore 岸 / shoreline 岸线 / offshore 离岸的 / onshore 陆上的 / shore up 支撑</li><li><strong>Memory Tip:</strong> shore 比 coast 更&quot;局部&quot;，且能用于湖泊河流（the shore of the lake）。shore up 本义是&quot;用支柱撑住&quot;，引申为&quot;支撑经济、信心&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词用 on the shore。</li><li>ashore 是副词：go ashore（上岸），不加介词。</li><li>offshore / onshore 成对记：离岸的 / 陆上的。</li></ul></div><div class="vocab-card"><h2 id="tide" tabindex="-1"><a class="header-anchor" href="#tide"><span>Tide</span></a></h2><p class="vc-meta"><strong>/taɪd/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>潮，潮汐</li><li>潮流，趋势（the tide of opinion）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>high tide</td><td>满潮，高潮</td></tr><tr><td>low tide</td><td>低潮</td></tr><tr><td>the tide comes in</td><td>涨潮</td></tr><tr><td>turn the tide</td><td>扭转局势</td></tr><tr><td>tide someone over</td><td>帮某人度过难关</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows the difference in water level between high and low tide.</p><blockquote><p>该示意图显示了满潮与低潮之间的水位差。</p></blockquote><p><strong>Writing Task 2</strong> Rising tides threaten to submerge parts of the delta within decades.</p><blockquote><p>不断上涨的潮水可能在几十年内淹没三角洲的部分地区。</p></blockquote><p><strong>Speaking</strong> We had to check the tide times before walking out to the island.</p><blockquote><p>走到那座岛之前，我们得先查一下潮汐时间。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>current</td><td>水流</td><td>指水体定向流动，非潮汐涨落</td></tr><tr><td>flood tide</td><td>涨潮</td><td>更技术化的说法</td></tr><tr><td>trend</td><td>趋势</td><td>只对应抽象义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>tid</em>（时间、时节）——潮水按时来去，故称 tide</li><li><strong>Family:</strong> tide 潮 / tidal 潮汐的 / tide over 帮度过难关 / tidings 消息</li><li><strong>Memory Tip:</strong> tid = 时间，同源词还有 time、tidy。tide sb over 字面像&quot;涨潮把船托过浅滩&quot;，所以是&quot;帮人撑过一段难日子&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>涨落潮说 the tide comes in / goes out，不用 <s>the tide rises up</s>。</li><li>high tide / low tide 前一般不加 the。</li><li>turn the tide 是&quot;扭转局势&quot;，不是&quot;转潮&quot;。</li></ul></div><div class="vocab-card"><h2 id="current" tabindex="-1"><a class="header-anchor" href="#current"><span>Current</span></a></h2><p class="vc-meta"><strong>/ˈkʌrənt/</strong> · noun · 名词 / adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：水流，气流；电流；潮流，趋势</li><li>形容词：当前的，现行的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>ocean current</td><td>洋流</td></tr><tr><td>electric current</td><td>电流</td></tr><tr><td>against the current</td><td>逆流</td></tr><tr><td>current affairs</td><td>时事</td></tr><tr><td>the current situation</td><td>当前形势</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows warm and cold ocean currents crossing the region.</p><blockquote><p>该地图显示了流经该地区的暖流与寒流。</p></blockquote><p><strong>Writing Task 2</strong> Ocean currents distribute heat and nutrients, shaping the climate of places far from the equator.</p><blockquote><p>洋流输送热量与养分，塑造着远离赤道地区的气候。</p></blockquote><p><strong>Speaking</strong> Don&#39;t swim here — the current is much stronger than it looks.</p><blockquote><p>别在这儿游泳，水流比看上去急得多。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>flow</td><td>流动</td><td>强调过程，不指具体水团</td></tr><tr><td>stream</td><td>水流</td><td>较窄、较定向</td></tr><tr><td>trend</td><td>趋势</td><td>只对应抽象义</td></tr><tr><td>present</td><td>现在的</td><td>形容词义，更中性</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>currere</em>（跑）→ <em>current</em>（流动之物）</li><li><strong>Family:</strong> current 水流；当前的 / currency 货币；通用 / occur 发生 / excursion 远足</li><li><strong>Memory Tip:</strong> currere = 跑。水在跑是 current，时间在跑是 current affairs（时事），钱在&quot;流通&quot;就是 currency。一条词根串起四个高频词。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>current（当前的）与 currant（葡萄干）只差一个字母。</li><li>形容词 current 前不加 the：the current situation，不是 <s>the current</s>。</li><li>表水流最好用 ocean current / water flow，独自说 a current 易生歧义（也可指电流）。</li></ul></div><div class="vocab-card"><h2 id="brook" tabindex="-1"><a class="header-anchor" href="#brook"><span>Brook</span></a></h2><p class="vc-meta"><strong>/brʊk/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：小溪，溪流</li><li>动词：容忍，容许（多用于否定句）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a babbling brook</td><td>潺潺的小溪</td></tr><tr><td>a mountain brook</td><td>山间小溪</td></tr><tr><td>a clear brook</td><td>清澈的溪流</td></tr><tr><td>brook no delay</td><td>不容拖延</td></tr><tr><td>brook no criticism</td><td>不容批评</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map marks a brook running from the hills down to the river.</p><blockquote><p>该地图标出了一条从丘陵流下汇入河流的小溪。</p></blockquote><p><strong>Writing Task 2</strong> Small brooks carry nutrients that sustain entire river systems downstream.</p><blockquote><p>小溪输送的养分维系着下游的整个河系。</p></blockquote><p><strong>Speaking</strong> There&#39;s a brook at the bottom of the garden — you can hear it from the bedroom.</p><blockquote><p>花园尽头有条小溪，在卧室就能听见水声。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>stream</td><td>溪流</td><td>更通用，大小皆可</td></tr><tr><td>creek</td><td>小溪</td><td>美式常用</td></tr><tr><td>rivulet</td><td>细流</td><td>书面，水量极小</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>brōc</em>（溪），与德语 <em>Bruch</em>（沼泽）同源</li><li><strong>Family:</strong> brook 小溪 / brooklet 细流 / brook no 不容</li><li><strong>Memory Tip:</strong> brook 兼&quot;小溪&quot;与&quot;容忍&quot;两义，联系在于&quot;容得下&quot;。动词义几乎只出现在否定句：brook no delay（不容拖延）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>动词 brook 只用于否定或疑问：He brooks no criticism。</li><li>别与 broke（break 的过去式）混。</li><li>brook 比 stream 更小、更文学化，写实报告里 stream 更稳。</li></ul></div><div class="vocab-card"><h2 id="stream" tabindex="-1"><a class="header-anchor" href="#stream"><span>Stream</span></a></h2><p class="vc-meta"><strong>/striːm/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：溪流，小河；（人、车的）一连串；数据流</li><li>动词：流动，涌出；在线播放</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a mountain stream</td><td>山涧</td></tr><tr><td>a steady stream of</td><td>源源不断的</td></tr><tr><td>stream down</td><td>不断流下</td></tr><tr><td>jet stream</td><td>急流（高空）</td></tr><tr><td>streaming service</td><td>流媒体服务</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the stream flowing south into the reservoir.</p><blockquote><p>该地图显示了这条溪流向南流入水库的路径。</p></blockquote><p><strong>Writing Task 2</strong> A steady stream of migrants has moved from rural villages to coastal cities.</p><blockquote><p>源源不断的移民从乡村涌向沿海城市。</p></blockquote><p><strong>Speaking</strong> Tears were streaming down her face, and she was still laughing.</p><blockquote><p>眼泪不停地从她脸上流下来，她却还在笑。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>brook</td><td>小溪</td><td>更小、更文学化</td></tr><tr><td>river</td><td>河</td><td>规模大，注入海或湖</td></tr><tr><td>flow</td><td>流动</td><td>强调动作而非实体</td></tr><tr><td>torrent</td><td>急流</td><td>水势猛，含危险意味</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>strēam</em>（流动），与德语 <em>Strom</em> 同源</li><li><strong>Family:</strong> stream 溪流 / mainstream 主流 / streamline 精简 / streamer 长条饰带</li><li><strong>Memory Tip:</strong> 一条&quot;流动的线&quot;：water stream 水流、a stream of people 人流、data stream 数据流、streaming 直播。mainstream（主流）也是它。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>a stream of 后接复数或不可数：a stream of traffic / visitors。</li><li>stream down 表示&quot;不断流下&quot;，介词别丢。</li><li>stream 与 river 是规模差别，地图题里要看图判断。</li></ul></div><div class="vocab-card"><h2 id="source" tabindex="-1"><a class="header-anchor" href="#source"><span>Source</span></a></h2><p class="vc-meta"><strong>/sɔːs/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>源头，水源（河流发源处）</li><li>来源，出处；消息人士</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the source of the river</td><td>河流的源头</td></tr><tr><td>a source of energy</td><td>能源来源</td></tr><tr><td>a reliable source</td><td>可靠的消息来源</td></tr><tr><td>at source</td><td>在源头</td></tr><tr><td>source material</td><td>原始材料</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map marks the source of the river high in the mountains.</p><blockquote><p>该地图标出了这条河在高山处的源头。</p></blockquote><p><strong>Writing Task 2</strong> Solar power has become the cheapest source of new electricity in many countries.</p><blockquote><p>太阳能已成为许多国家最廉价的新增电力来源。</p></blockquote><p><strong>Speaking</strong> The source of the leak turned out to be a loose pipe under the sink.</p><blockquote><p>漏水的原因原来是水槽下面一根松了的管子。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>origin</td><td>起源</td><td>偏时间与成因，不指水源</td></tr><tr><td>spring</td><td>泉眼</td><td>具体出水点，规模小</td></tr><tr><td>root</td><td>根源</td><td>强调原因，多用于问题</td></tr><tr><td>supply</td><td>供给（源）</td><td>强调可用量</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>surgere</em>（涌出、升起）→ <em>source</em></li><li><strong>Family:</strong> source 源头 / resource 资源 / surge 激增 / resurrect 复活</li><li><strong>Memory Tip:</strong> surgere = 涌出。水涌出的地方是 source；re-（反复）+ source = resource，即可反复取用的&quot;来源&quot;——这就是&quot;资源&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;河的源头&quot;说 the source of the river，介词用 of。</li><li>&quot;消息来源&quot;是 a source of information，也可说 a source close to…</li><li>resource 是&quot;资源&quot;，别漏掉前缀 re-。</li></ul></div><div class="vocab-card"><h2 id="shallow" tabindex="-1"><a class="header-anchor" href="#shallow"><span>Shallow</span></a></h2><p class="vc-meta"><strong>/ˈʃæləʊ/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>浅的（水、土层、容器）</li><li>肤浅的，表面的（思想、论证）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>shallow water</td><td>浅水</td></tr><tr><td>shallow soil</td><td>浅薄的土层</td></tr><tr><td>the shallow end</td><td>（泳池）浅水区</td></tr><tr><td>a shallow argument</td><td>站不住脚的论证</td></tr><tr><td>the shallows</td><td>浅滩（名词）</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows that the water is shallowest close to the shore.</p><blockquote><p>该示意图显示近岸处的水最浅。</p></blockquote><p><strong>Writing Task 2</strong> Shallow coastal waters support some of the most productive fisheries in the world.</p><blockquote><p>浅海近岸水域支撑着世界上一些产量最高的渔场。</p></blockquote><p><strong>Speaking</strong> The pool&#39;s shallow end is only a metre deep, so it&#39;s fine for kids.</p><blockquote><p>泳池浅水区只有一米深，小孩玩没问题。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>superficial</td><td>表面的，肤浅的</td><td>只对应抽象义，且带贬义</td></tr><tr><td>skin-deep</td><td>表面的</td><td>口语，多形容感情、美观</td></tr><tr><td>shoal</td><td>浅滩</td><td>名词，指具体浅水区</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>sceald</em>（浅）</li><li><strong>Family:</strong> shallow 浅的 / shallows 浅滩 / shallowly 浅地 / shallowness 浅薄</li><li><strong>Memory Tip:</strong> 一个词两条线：水浅 → 人浅。反义都是 deep：shallow water ↔ deep water，a shallow person ↔ a deep thinker。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;水位低&quot;是 low water，不是 <s>shallow water</s>（后者指水浅）。</li><li>比较级 shallower，最高级 shallowest。</li><li>比喻义多形容论证、分析、人，带批评色彩，正式写作中慎用。</li></ul></div><div class="vocab-card"><h2 id="superficial" tabindex="-1"><a class="header-anchor" href="#superficial"><span>Superficial</span></a></h2><p class="vc-meta"><strong>/ˌsuːpəˈfɪʃl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>表面的（损伤、相似）</li><li>肤浅的，不深入的（了解、分析）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>superficial damage</td><td>表面损伤</td></tr><tr><td>a superficial resemblance</td><td>表面上的相似</td></tr><tr><td>superficial knowledge</td><td>一知半解</td></tr><tr><td>superficial wounds</td><td>皮外伤</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows that the earthquake caused only superficial damage to the coastal road.</p><blockquote><p>该地图显示地震对沿海公路只造成了表面损伤。</p></blockquote><p><strong>Writing Task 2</strong> A superficial reading of the data suggests steady growth, but the trend reverses once inflation is taken into account.</p><blockquote><p>粗看数据似乎是稳步增长，但一旦计入通胀，趋势就反转了。</p></blockquote><p><strong>Speaking</strong> We only have a superficial understanding of how the system actually works.</p><blockquote><p>我们对这套系统实际怎么运转只有很表面的了解。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>shallow</td><td>肤浅的</td><td>更口语，可直接形容人</td></tr><tr><td>cursory</td><td>草率的</td><td>强调匆忙、不仔细</td></tr><tr><td>cosmetic</td><td>表面的</td><td>指只改外观，不解决实质</td></tr><tr><td>surface-level</td><td>表层的</td><td>中性偏口语</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>super-</em>（在上）+ <em>facies</em>（脸、表面）→ <em>superficialis</em></li><li><strong>Family:</strong> superficial 表面的 / surface 表面 / face 脸 / facade 建筑立面</li><li><strong>Memory Tip:</strong> facies = 脸。super-（在上）+ facies = &quot;只在脸皮那一层&quot;。所以它既能说 surface damage，也能说 a superficial analysis。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 super-fi-ci-al，别写成 <s>superfical</s>。</li><li>形容&quot;了解、分析&quot;时带贬义，别用来夸人&quot;简明&quot;。</li><li>描述物理损伤时是中性的（superficial damage 表面损伤）。</li></ul></div><div class="vocab-card"><h2 id="reservoir" tabindex="-1"><a class="header-anchor" href="#reservoir"><span>Reservoir</span></a></h2><p class="vc-meta"><strong>/ˈrezəvwɑː(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>水库，蓄水池</li><li>（知识、人才的）储备，蓄积</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a water reservoir</td><td>水库</td></tr><tr><td>reservoir levels</td><td>水库水位</td></tr><tr><td>a reservoir of knowledge</td><td>知识储备</td></tr><tr><td>an oil reservoir</td><td>石油储层</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a reservoir supplying the city to the south.</p><blockquote><p>该地图显示了为南部城市供水的一座水库。</p></blockquote><p><strong>Writing Task 2</strong> Reservoirs buffer seasonal variation, storing water in the wet season for use in the dry.</p><blockquote><p>水库能缓冲季节性波动，在雨季蓄水供旱季使用。</p></blockquote><p><strong>Speaking</strong> The reservoir is at its lowest level in twenty years.</p><blockquote><p>水库水位处于二十年来的最低点。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>tank</td><td>水箱</td><td>人工容器，规模小</td></tr><tr><td>lake</td><td>湖</td><td>天然水体</td></tr><tr><td>store</td><td>储备</td><td>抽象用法更广</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 法语 <em>réservoir</em> ← <em>réserver</em>（保留）</li><li><strong>Family:</strong> reservoir 水库 / reserve 储备；预订 / reservation 预约；保留</li><li><strong>Memory Tip:</strong> 法语&quot;储存之处&quot;。比喻义 a reservoir of talent（人才储备）在写作里很出彩，比 a lot of talent 有层次。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a reservoir / reservoirs。</li><li>&quot;水库水位&quot;是 reservoir levels。</li><li>发音 /ˈrezəvwɑː(r)/，英式词尾 r 不发音。</li></ul></div><div class="vocab-card"><h2 id="waterfall" tabindex="-1"><a class="header-anchor" href="#waterfall"><span>Waterfall</span></a></h2><p class="vc-meta"><strong>/ˈwɔːtəfɔːl/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>瀑布</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a spectacular waterfall</td><td>壮观的瀑布</td></tr><tr><td>a waterfall drops</td><td>瀑布跌落</td></tr><tr><td>the foot of the waterfall</td><td>瀑布脚下</td></tr><tr><td>waterfall model</td><td>瀑布模型（软件）</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a waterfall where the river drops over a resistant rock ledge.</p><blockquote><p>该地图显示了一处河水流过坚硬岩坎跌落的瀑布。</p></blockquote><p><strong>Writing Task 2</strong> Waterfalls retreat upstream over time as the rock beneath them is eroded.</p><blockquote><p>随着下方岩石被侵蚀，瀑布会随时间向上游后退。</p></blockquote><p><strong>Speaking</strong> We swam in the pool at the bottom of the waterfall.</p><blockquote><p>我们在瀑布下的水潭里游泳。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>falls</td><td>瀑布</td><td>大瀑布多用复数</td></tr><tr><td>cascade</td><td>叠瀑</td><td>一串小跌水</td></tr><tr><td>cataract</td><td>大瀑布</td><td>文学化，也指&quot;白内障&quot;</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>water</em>（水）+ <em>fall</em>（落下）</li><li><strong>Family:</strong> waterfall 瀑布 / falls 瀑布 / cascade 层叠瀑布 / watercourse 水道</li><li><strong>Memory Tip:</strong> 大瀑布常用复数：Niagara Falls。cascade 指一级一级的叠水，规模小、层次多。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a waterfall / waterfalls。</li><li>专名常作复数：Niagara Falls。</li><li>与 cascade 区分：一个是整体跌落，一个是层层跌落。</li></ul></div><div class="vocab-card"><h2 id="fountain" tabindex="-1"><a class="header-anchor" href="#fountain"><span>Fountain</span></a></h2><p class="vc-meta"><strong>/ˈfaʊntən/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>喷泉，人造泉</li><li>源泉，来源</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a fountain in the square</td><td>广场上的喷泉</td></tr><tr><td>a fountain pen</td><td>钢笔</td></tr><tr><td>the fountain of youth</td><td>青春之泉</td></tr><tr><td>a fountain of knowledge</td><td>知识的源泉</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a fountain at the centre of the square.</p><blockquote><p>该地图显示了广场中央的一座喷泉。</p></blockquote><p><strong>Writing Task 2</strong> Public fountains once supplied most of the city&#39;s drinking water.</p><blockquote><p>公共喷泉曾供应着这座城市大部分的饮用水。</p></blockquote><p><strong>Speaking</strong> We met by the fountain at noon.</p><blockquote><p>我们中午在喷泉边碰面。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>spring</td><td>泉</td><td>天然出水点</td></tr><tr><td>jet</td><td>喷射</td><td>指水柱本身</td></tr><tr><td>well</td><td>井</td><td>取水设施，非喷水</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>fons</em>（泉源）</li><li><strong>Family:</strong> fountain 喷泉 / fount 源泉 / fountainhead 源头 / fountain pen 钢笔</li><li><strong>Memory Tip:</strong> fons = 泉。fountain pen 字面是&quot;墨水的泉&quot;，所以是自来水笔；the fountain of youth 是神话里的青春之泉。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a fountain / fountains。</li><li>fountain 是人造的，天然出水点用 spring。</li><li>比喻义 a fountain of knowledge（知识源泉）适合写作。</li></ul></div><div class="vocab-card"><h2 id="spring" tabindex="-1"><a class="header-anchor" href="#spring"><span>Spring</span></a></h2><p class="vc-meta"><strong>/sprɪŋ/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：春天；泉，泉水；弹簧</li><li>动词：跳起，弹起；涌现（spring up）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a hot spring</td><td>温泉</td></tr><tr><td>in spring</td><td>在春天</td></tr><tr><td>spring water</td><td>泉水</td></tr><tr><td>spring up</td><td>涌现，冒出来</td></tr><tr><td>spring from</td><td>源自</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a spring that feeds the upper reaches of the river.</p><blockquote><p>该地图显示了一处为河流上游供水的泉眼。</p></blockquote><p><strong>Writing Task 2</strong> Hot springs indicate geothermal activity below the surface.</p><blockquote><p>温泉表明地表之下存在地热活动。</p></blockquote><p><strong>Speaking</strong> There&#39;s a spring behind the house — the water&#39;s drinkable.</p><blockquote><p>房子后面有处泉水，能直接喝。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>fountain</td><td>喷泉</td><td>人造的喷水景观</td></tr><tr><td>source</td><td>源头</td><td>泛指起点，非出水点</td></tr><tr><td>well</td><td>井</td><td>人工取水构筑物</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>springan</em>（跳起、涌出）</li><li><strong>Family:</strong> spring 春天；泉；弹簧 / springy 有弹性的 / offspring 后代 / spring water 泉水</li><li><strong>Memory Tip:</strong> 一个&quot;跳&quot;字统摄四义：春天（万物跃出）、泉（水跃出地面）、弹簧（弹起）、跳跃（spring up）。同根 offspring 就是&quot;从身上跳出来的&quot;——后代。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;在春天&quot;用 in spring，不加 the。</li><li>温泉是 hot spring（两个词）。</li><li>spring up 表&quot;涌现&quot;：New shops sprang up overnight。</li></ul></div><div class="vocab-card"><h2 id="pour" tabindex="-1"><a class="header-anchor" href="#pour"><span>Pour</span></a></h2><p class="vc-meta"><strong>/pɔː(r)/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>倒，灌（液体）</li><li>（雨）倾盆而下；涌出</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>pour water into</td><td>把水倒进</td></tr><tr><td>pour out</td><td>倒出；倾诉</td></tr><tr><td>it&#39;s pouring</td><td>下大雨</td></tr><tr><td>pour down</td><td>倾泻而下</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows water poured onto the trial plots each week.</p><blockquote><p>该图表显示了每周浇到试验地块上的水量。</p></blockquote><p><strong>Writing Task 2</strong> Heavy rain poured for three days, overwhelming the drains.</p><blockquote><p>大雨连下三天，排水系统不堪负荷。</p></blockquote><p><strong>Speaking</strong> It was pouring, so we stayed in and watched films.</p><blockquote><p>当时下着大雨，我们就待在家里看电影。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>tip</td><td>倾倒</td><td>动作更随意</td></tr><tr><td>decant</td><td>倒出</td><td>正式，指滗出清液</td></tr><tr><td>stream</td><td>流淌</td><td>强调连续流动</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古法语 <em>purer</em>（倾倒、筛滤）</li><li><strong>Family:</strong> pour 倒 / downpour 暴雨 / pouring 倾盆的 / pour out 倾诉</li><li><strong>Memory Tip:</strong> 两个方向：往里倒（pour water into the glass）与往外倾泻（it&#39;s pouring）。pour out 还能表&quot;倾诉心事&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>it&#39;s pouring 是&quot;下大雨&quot;的口语，不是&quot;在倒东西&quot;。</li><li>pour 是规则动词：poured / pouring。</li><li>名词&quot;暴雨&quot;是 downpour，一个词。</li></ul></div><div class="vocab-card"><h2 id="drain" tabindex="-1"><a class="header-anchor" href="#drain"><span>Drain</span></a></h2><p class="vc-meta"><strong>/dreɪn/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：排水管，下水道；排水沟</li><li>动词：排干，排水；耗尽</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a storm drain</td><td>雨水管</td></tr><tr><td>drain the land</td><td>排干土地</td></tr><tr><td>drain away</td><td>排走，流走</td></tr><tr><td>brain drain</td><td>人才外流</td></tr><tr><td>down the drain</td><td>白费，付诸东流</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows drainage channels running towards the river.</p><blockquote><p>该地图显示了通向河流的排水渠道。</p></blockquote><p><strong>Writing Task 2</strong> Draining wetlands for farmland destroys habitats and raises flood risk downstream.</p><blockquote><p>排干湿地改农田会破坏生境，并增加下游洪涝风险。</p></blockquote><p><strong>Speaking</strong> The sink&#39;s blocked — the water won&#39;t drain.</p><blockquote><p>水槽堵了，水排不下去。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>sewer</td><td>下水道</td><td>指污水管道系统</td></tr><tr><td>channel</td><td>渠道</td><td>人工或天然水沟</td></tr><tr><td>deplete</td><td>耗尽</td><td>只对应抽象&quot;耗尽&quot;义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>dreahnian</em>（滤干）</li><li><strong>Family:</strong> drain 排水 / drainage 排水系统 / drainpipe 排水管 / brain drain 人才外流</li><li><strong>Memory Tip:</strong> 两个习语都从&quot;流走&quot;来：brain drain（人才外流）、down the drain（白费）。写作里 drain 当动词表&quot;耗尽资源&quot;也很好用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>及物、不及物都可用：drain the field / water drains away。</li><li>名词&quot;排水系统&quot;是 drainage，不是 <s>drainment</s>。</li><li>&quot;排水沟&quot;常说 drainage channel / ditch。</li></ul></div><div class="vocab-card"><h2 id="drip" tabindex="-1"><a class="header-anchor" href="#drip"><span>Drip</span></a></h2><p class="vc-meta"><strong>/drɪp/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>动词：滴下，滴水</li><li>名词：水滴，滴落；滴液；（口语）乏味的人</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>drip from</td><td>从……滴下</td></tr><tr><td>drip irrigation</td><td>滴灌</td></tr><tr><td>a dripping tap</td><td>滴水的龙头</td></tr><tr><td>drip feed</td><td>滴注；缓慢供给</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows drip irrigation delivering water directly to plant roots.</p><blockquote><p>该示意图显示了滴灌把水直接送到植物根部。</p></blockquote><p><strong>Writing Task 2</strong> A dripping tap can waste thousands of litres of water a year.</p><blockquote><p>一个滴水的龙头一年能浪费数千升水。</p></blockquote><p><strong>Speaking</strong> The tap&#39;s been dripping all night — it&#39;s driving me mad.</p><blockquote><p>龙头滴了一整夜，快把我逼疯了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>trickle</td><td>细流</td><td>连续小流，非一滴一滴</td></tr><tr><td>leak</td><td>漏</td><td>强调容器破损</td></tr><tr><td>dribble</td><td>滴落</td><td>也指流口水</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 中古英语 <em>drippen</em>（滴）</li><li><strong>Family:</strong> drip 滴 / dripping 滴水的 / drip irrigation 滴灌 / drippy 湿淋淋的</li><li><strong>Memory Tip:</strong> drip irrigation（滴灌）是农业地理高频词，与 sprinkler irrigation（喷灌）对照记：一个滴到根、一个喷到空中。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>名词可数：a drip。</li><li>drip irrigation 两个词分开写。</li><li>drip（一滴一滴落）与 drop（一滴水）不同，后者是名词&quot;水滴&quot;。</li></ul></div><div class="vocab-card"><h2 id="drown" tabindex="-1"><a class="header-anchor" href="#drown"><span>Drown</span></a></h2><p class="vc-meta"><strong>/draʊn/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>淹死，溺死</li><li>淹没；（声音）盖过</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>drown in</td><td>淹死于……</td></tr><tr><td>be drowned out</td><td>（声音）被盖过</td></tr><tr><td>drown out the noise</td><td>盖过噪声</td></tr><tr><td>drown in debt</td><td>债台高筑</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows deaths from drowning during the monsoon season.</p><blockquote><p>该图表显示了季风季节的溺亡人数。</p></blockquote><p><strong>Writing Task 2</strong> Rising seas could drown low-lying islands within decades.</p><blockquote><p>海平面上升可能在几十年内淹没低洼岛屿。</p></blockquote><p><strong>Speaking</strong> He nearly drowned in the river when he was a child.</p><blockquote><p>他小时候在河里差点淹死。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>submerge</td><td>淹没</td><td>强调没入水下，未必致死</td></tr><tr><td>flood</td><td>淹没</td><td>指水漫过陆地</td></tr><tr><td>suffocate</td><td>窒息</td><td>强调缺氧致死，非水</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>druncnian</em>（淹死），与 <em>drink</em> 同源</li><li><strong>Family:</strong> drown 淹死 / drowning 溺水 / drowned 淹死的</li><li><strong>Memory Tip:</strong> drown out 是&quot;声音盖过声音&quot;：The music drowned out the traffic。这个用法在描述噪音污染时很好用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>drown 是&quot;淹死&quot;（结果），不是&quot;在水里玩&quot;。</li><li>be drowned 表&quot;被淹死&quot;，drown 也可作不及物。</li><li>drown out 是短语动词，别漏 out。</li></ul></div><div class="vocab-card"><h2 id="emerge" tabindex="-1"><a class="header-anchor" href="#emerge"><span>Emerge</span></a></h2><p class="vc-meta"><strong>/ɪˈmɜːdʒ/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>出现，浮现（从隐蔽处出来）</li><li>（事实）显露，暴露</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>emerge from</td><td>从……中出现</td></tr><tr><td>emerge as</td><td>成为，崭露头角</td></tr><tr><td>it emerged that</td><td>后经披露……</td></tr><tr><td>emerging markets</td><td>新兴市场</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows a clear pattern emerging after 2010.</p><blockquote><p>该图表显示了 2010 年后浮现出的明显规律。</p></blockquote><p><strong>Writing Task 2</strong> It has emerged that the policy benefited urban households far more than rural ones.</p><blockquote><p>后经披露，该政策对城市家庭的助益远大于农村家庭。</p></blockquote><p><strong>Speaking</strong> The sun emerged from behind the clouds just as we reached the top.</p><blockquote><p>我们刚到山顶，太阳就从云后露了出来。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>appear</td><td>出现</td><td>最通用，无&quot;浮现&quot;意味</td></tr><tr><td>surface</td><td>浮现</td><td>强调从隐藏状态显露</td></tr><tr><td>arise</td><td>产生</td><td>多指问题、机会出现</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>e-</em>（出）+ 拉丁 <em>mergere</em>（浸入）→ &quot;从浸没中出来&quot;</li><li><strong>Family:</strong> emerge 出现 / emergence 出现 / emerging 新兴的 / merge 合并 / emergency 紧急情况</li><li><strong>Memory Tip:</strong> e-（出）+ merge（浸入）= 从水里冒出来。emerging markets（新兴市场）是经济类高频搭配；emergency 也同族，指&quot;突然冒出来的事&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词常见 from：emerge from the water。</li><li>It emerged that… 是正式句式，写作里显得有分量。</li><li>emergency 是名词&quot;紧急情况&quot;，拼写与 emerge 无关。</li></ul></div><div class="vocab-card"><h2 id="float" tabindex="-1"><a class="header-anchor" href="#float"><span>Float</span></a></h2><p class="vc-meta"><strong>/fləʊt/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>动词：漂浮；（在水面）漂流；提出（想法）</li><li>名词：浮标；彩车；备用零钱</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>float on water</td><td>浮在水面</td></tr><tr><td>float downstream</td><td>顺流漂下</td></tr><tr><td>float an idea</td><td>试探性提出想法</td></tr><tr><td>a parade float</td><td>游行彩车</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how plastic debris floats on ocean currents.</p><blockquote><p>该示意图显示了塑料碎片如何漂浮在洋流之上。</p></blockquote><p><strong>Writing Task 2</strong> Ice floats because it is less dense than the water beneath it.</p><blockquote><p>冰能浮起来，是因为它的密度小于下方的水。</p></blockquote><p><strong>Speaking</strong> We floated down the river on old tyres.</p><blockquote><p>我们坐在旧轮胎上顺河漂流。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>drift</td><td>漂流</td><td>强调被水流带走</td></tr><tr><td>hover</td><td>悬停</td><td>指空中停留</td></tr><tr><td>bob</td><td>上下浮动</td><td>强调起伏晃动</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>flotian</em>，与 <em>fleet</em>、<em>flow</em> 同源</li><li><strong>Family:</strong> float 漂浮 / floating 漂浮的 / afloat 漂浮着；不欠债的 / floatation 漂浮</li><li><strong>Memory Tip:</strong> float（不沉）与 drift（随流而动）分工不同：冰能 float，瓶子会 drift。stay afloat 引申为&quot;维持经营&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>浮在水面用 float on water，介词是 on。</li><li>afloat 是表语形容词：keep the company afloat。</li><li>拼写 float，别与 flout（藐视）混。</li></ul></div>`,27)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};